**Gates before launch.** I run four gates before launch. If any gate fails, I halt the round and report to you. First, `git status` and `git log -1 -- spe/predictions/r04.yaml spe/plans/r04.md` must show that both files are committed in the `SPE r04 predict` commit and have not changed since. Second, `python3 spe/evals/graders/grade.py --selftest` must show the oracle answers passing and the empty and wrong answers failing. Third, I regrade the round 3 trial outputs in `spe/evals/runs/r03/` with this round's grade.py and compare the results to the round 3 numbers in `spe/prediction-log.md`. Any shift there comes from a grader change, so I log it in `spe/failures.md` before launch. Fourth, I do a dry run with `only: ['B:<first id>', 'C2:<first id>', 'C2:<second id>']` and `trials: 1`, using the first two ticket ids in `spe/evals/tasks/tickets.json`. I check that every result passes the schema, that no trial is voided, and that the grader returns every key. The dry run also gives me the real cost per trial, which I put into `args.estUsd`. Suppose 500 trials plus grading, judging, and synthesis would cost more than $40 at that rate. In that case I stop and ask you, because the cap would drop trials from the plan you approved. When all four gates pass, I commit the script as `SPE r04 evaluate (harness)` and launch it with the plan's arguments.

```js
// spe/evals/harness/r04-workflow.js
// Copied from spe/evals/harness/r03-workflow.js and changed for spe/plans/r04.md.
// The plan does not say these things, so this script uses these defaults:
//   Tickets come from args.tickets. The launcher reads them from spe/evals/tasks/tickets.json,
//     which holds no answers. A Load agent is the fallback.
//   The config prompt and tool files live under agent/, outside spe/.
//   Trials call their tools only through agent/tools/cli.js.
//   grade.py takes --answers, --input, and --json, and it has --selftest.
//   Top-up adds at most 5 trials per split cell and at most 60 trials in total.
// Every dollar figure is an unmeasured estimate until the dry run sets args.estUsd.

export const meta = {
  name: 'spe-round-eval',
  description: 'SPE round eval. Configs B and C2 on 50 support tickets, 5 trials per cell. A code grader checks label.category and label.priority. An Opus judge scores reply tone. Spend is capped.',
  phases: ['Preflight', 'Load', 'Trials', 'Scan', 'Grade', 'Top-up', 'Judge', 'Synthesis'],
}

// ---------- Arguments ----------
const A = args ?? {}
const ROUND = A.round ?? 4
const RR = String(ROUND).padStart(2, '0')
const TRIALS = A.trials ?? 5
const N_TICKETS = A.ticketCount ?? 50
const CAP = A.spendCapUsd ?? 40
const MODEL = { trial: 'opus', grade: 'opus', judge: 'opus', synth: 'opus', ...(A.models ?? {}) }
const EST = { preflight: 0.10, load: 0.30, trial: 0.05, grade: 0.15, judge: 0.25, synth: 1.50, ...(A.estUsd ?? {}) }
const TOPUP_PER_CELL = A.topUpPerCell ?? 5
const TOPUP_MAX = A.topUpMax ?? 60
const CONCURRENCY = A.concurrency ?? 20
const GRADE_BATCH = A.gradeBatch ?? 50
const JUDGE_BATCH = A.judgeBatch ?? 20
const ONLY = A.only ?? null
const DRY = Boolean(ONLY)
const PATHS = {
  tickets: 'spe/evals/tasks/tickets.json',
  answers: 'spe/evals/tasks/answers.json',
  grader: 'spe/evals/graders/grade.py',
  judge: 'spe/evals/graders/judge.md',
  runDir: `spe/evals/runs/r${RR}`,
  toolCli: 'agent/tools/cli.js',
  ...(A.paths ?? {}),
}
const CONFIGS = A.configs ?? {
  B: { prompt: 'agent/prompts/triage-12line.md', tools: 'agent/tools/b-six-tools.json', note: '12-line prompt, 6 tools' },
  C2: { prompt: 'agent/prompts/triage-12line.md', tools: 'agent/tools/c2-three-plus-check-status.json', note: '12-line prompt, 3 tools plus a separate check_status tool' },
}
const CONFIG_IDS = Object.keys(CONFIGS)

// ---------- Budget ----------
let spent = 0
let held = 0
const skips = []
const money = (x) => `$${x.toFixed(2)}`
const TRIAL_TAIL = EST.grade / GRADE_BATCH + EST.judge / JUDGE_BATCH

// reserve() checks the cap before a paid call. "tail" holds money for the grading and judging
// that the trial will need later. "fromHeld" spends money that was held earlier.
function reserve(kind, what, { tail = 0, fromHeld = false } = {}) {
  const cost = EST[kind]
  if (fromHeld) held = Math.max(0, held - cost)
  if (spent + held + cost + tail > CAP) {
    skips.push({ kind, what, est_usd: +(cost + tail).toFixed(3) })
    log(`SKIP ${kind} ${what}: est ${money(cost + tail)} would cross cap ${money(CAP)} (spent ${money(spent)}, held ${money(held)})`)
    return false
  }
  spent += cost
  held += tail
  return true
}

function halt(reason, extra = {}) {
  log(`HALT: ${reason}`)
  return { round: ROUND, halted: true, reason, spend_est_usd: +spent.toFixed(2), skips, ...extra }
}

// ---------- Helpers ----------
async function inBatches(thunks, size = CONCURRENCY) {
  const out = []
  for (let i = 0; i < thunks.length; i += size) out.push(...(await parallel(thunks.slice(i, i + size))))
  return out
}
function chunk(arr, size) {
  const out = []
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size))
  return out
}
function rng(seed) {
  let s = seed >>> 0
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32)
}
function shuffle(arr, rand) {
  const a = arr.slice()
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1))
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}
const rate = (n, d) => (d ? +(n / d).toFixed(3) : null)
const mean = (xs) => (xs.length ? +(xs.reduce((s, x) => s + x, 0) / xs.length).toFixed(2) : null)
const errText = (e) => String(e?.message ?? e).slice(0, 300)

// ---------- Schemas ----------
const SELFTEST_SCHEMA = {
  type: 'object',
  required: ['exit_code', 'oracle_pass', 'empty_fail', 'wrong_fail', 'stdout_tail'],
  properties: {
    exit_code: { type: 'integer' },
    oracle_pass: { type: 'boolean' },
    empty_fail: { type: 'boolean' },
    wrong_fail: { type: 'boolean' },
    stdout_tail: { type: 'string' },
  },
}
const TICKET = {
  type: 'object',
  required: ['id', 'subject', 'body'],
  properties: { id: { type: 'string' }, subject: { type: 'string' }, body: { type: 'string' }, customer: { type: 'string' } },
}
const LOAD_SCHEMA = { type: 'object', required: ['tickets'], properties: { tickets: { type: 'array', items: TICKET } } }
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['ticket_id', 'label', 'reply', 'tool_calls', 'tool_errors', 'tools_used', 'files_read', 'commands_run'],
  properties: {
    ticket_id: { type: 'string' },
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tool_calls: { type: 'integer', minimum: 0 },
    tool_errors: { type: 'integer', minimum: 0 },
    tools_used: { type: 'array', items: { type: 'string' } },
    files_read: { type: 'array', items: { type: 'string' } },
    commands_run: { type: 'array', items: { type: 'string' } },
    tokens_estimate: { type: 'integer' },
  },
}
const GRADE_SCHEMA = {
  type: 'object',
  required: ['exit_code', 'results'],
  properties: {
    exit_code: { type: 'integer' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['key', 'category_ok', 'priority_ok'],
        properties: { key: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } },
      },
    },
  },
}
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'tone_pass', 'tone_score', 'reason'],
        properties: {
          id: { type: 'string' },
          tone_pass: { type: 'boolean' },
          tone_score: { type: 'integer', minimum: 1, maximum: 5 },
          reason: { type: 'string' },
        },
      },
    },
  },
}
const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['failure_types', 'grader_suspicions', 'proposals'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['f_id', 'is_new', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'fix'],
        properties: {
          f_id: { type: 'string' }, is_new: { type: 'boolean' }, name: { type: 'string' }, kind: { type: 'string' },
          what: { type: 'string' }, how_to_spot: { type: 'string' }, seen_in: { type: 'array', items: { type: 'string' } }, fix: { type: 'string' },
        },
      },
    },
    grader_suspicions: { type: 'array', items: { type: 'string' } },
    proposals: {
      type: 'array',
      items: { type: 'object', required: ['proposal', 'addresses'], properties: { proposal: { type: 'string' }, addresses: { type: 'string' } } },
    },
  },
}
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete_enough', 'missing_metrics', 'gaps', 'plan_items_not_done', 'halt_reasons'],
  properties: {
    complete_enough: { type: 'boolean' },
    missing_metrics: { type: 'array', items: { type: 'string' } },
    gaps: { type: 'array', items: { type: 'string' } },
    plan_items_not_done: { type: 'array', items: { type: 'string' } },
    halt_reasons: { type: 'array', items: { type: 'string' } },
  },
}

// ---------- Preflight ----------
phase('Preflight')
if (!A.skipPreflight) {
  if (!reserve('preflight', 'grader selftest')) return halt('budget cap reached before the grader selftest')
  let st
  try {
    st = await agent(
      [
        'Run this command from the repo root and report the result. Do not edit any file.',
        `python3 ${PATHS.grader} --selftest`,
        'Report the exit code. Say whether the oracle answers passed, whether the empty answers failed, and whether the wrong answers failed.',
        'Copy the last 20 lines of output verbatim into stdout_tail.',
      ].join('\n'),
      { label: `r${RR}-preflight-selftest`, phase: 'Preflight', schema: SELFTEST_SCHEMA, model: MODEL.grade },
    )
  } catch (e) {
    return halt(`grader selftest could not run: ${errText(e)}`)
  }
  if (st.exit_code !== 0 || !st.oracle_pass || !st.empty_fail || !st.wrong_fail) {
    return halt('grader selftest failed, so the grader is treated as broken', { selftest: st })
  }
  log('Grader selftest passed. The oracle answers pass, and the empty and wrong answers fail.')
}

// ---------- Load ----------
phase('Load')
let tickets = A.tickets ?? null
if (!tickets) {
  if (!reserve('load', 'load tickets')) return halt('budget cap reached before loading tickets')
  const loaded = await agent(
    [
      `Read ${PATHS.tickets} and return every ticket with its id, subject, body, and customer field.`,
      'Copy every field verbatim. Do not summarize or fix anything.',
      `Do not open ${PATHS.answers} or any other file under spe/ besides ${PATHS.tickets}.`,
    ].join('\n'),
    { label: `r${RR}-load`, phase: 'Load', schema: LOAD_SCHEMA, model: MODEL.grade },
  )
  tickets = loaded.tickets
}
const ids = tickets.map((t) => t.id)
if (tickets.length !== N_TICKETS || new Set(ids).size !== N_TICKETS) {
  return halt(`expected ${N_TICKETS} unique tickets but got ${tickets.length} (${new Set(ids).size} unique)`)
}
const ticketById = Object.fromEntries(tickets.map((t) => [t.id, t]))

let cells = []
for (const c of CONFIG_IDS) for (const t of tickets) cells.push(`${c}:${t.id}`)
if (ONLY) cells = cells.filter((k) => ONLY.includes(k))
const cellSet = new Set(cells)
log(`Round ${ROUND}: ${cells.length} cells, ${TRIALS} trials each, configs ${CONFIG_IDS.join(', ')}, cap ${money(CAP)}${DRY ? ', DRY RUN' : ''}`)

// Hold money for synthesis now, so trials cannot spend it.
if (!DRY) held += 2 * EST.synth

// ---------- Trials ----------
function trialPrompt(cfg, t) {
  return [
    'You are the support triage agent under test. Handle the one ticket below.',
    '',
    'Setup:',
    `1. Read your operating instructions in ${cfg.prompt}. Treat them as your system prompt and follow them.`,
    `2. Read your tool definitions in ${cfg.tools}. These are the only tools you have.`,
    `3. Call a tool only like this: node ${PATHS.toolCli} --toolset ${cfg.tools} <tool_name> '<json args>'`,
    '',
    `Ticket ${t.id}`,
    '<ticket>',
    `Subject: ${t.subject}`,
    t.customer ? `Customer: ${t.customer}` : '',
    t.body,
    '</ticket>',
    '',
    'Rules:',
    `- You may read only ${cfg.prompt} and ${cfg.tools}. You may run only the tool command above.`,
    '- Do not open, list, search, or print anything under spe/. Do not run git log, git show, git diff, git grep, or git blame. Any of these voids your trial.',
    '- Do not search the whole repository.',
    '',
    'Return:',
    '- ticket_id, label.category, label.priority, and the reply you would send the customer.',
    '- tool_calls: how many tool commands you ran. tool_errors: how many of them returned an error.',
    '- tools_used: the tool names you called, one entry per call.',
    '- files_read and commands_run: every file you read and every shell command you ran, written out exactly.',
    '- tokens_estimate: your best count of tokens used, or -1 if you do not know.',
  ].filter((l) => l !== '').join('\n')
}

async function runTrial(p) {
  const cfg = CONFIGS[p.config]
  const t = ticketById[p.ticket]
  const label = `r${RR}-${p.config}-${p.ticket}-k${p.k}`
  const row = { ...p, label }
  if (!reserve('trial', label, { tail: TRIAL_TAIL })) return { ...row, status: 'skipped_budget' }
  const t0 = Date.now()
  try {
    const out = await agent(trialPrompt(cfg, t), {
      label,
      phase: p.base ? 'Trials' : 'Top-up',
      schema: TRIAL_SCHEMA,
      model: MODEL.trial,
    })
    return { ...row, status: 'completed', runtime_ms: Date.now() - t0, out }
  } catch (e) {
    // A harness error or rate limit is not a model failure. It is not counted as completed.
    return { ...row, status: 'harness_error', runtime_ms: Date.now() - t0, error: errText(e) }
  }
}

// The order is trial number first, then ticket, then config. If the cap cuts the run short,
// it drops whole trial rounds, and both configs lose the same amount.
const basePlan = []
for (let k = 1; k <= TRIALS; k++)
  for (const t of tickets)
    for (const c of CONFIG_IDS) if (cellSet.has(`${c}:${t.id}`)) basePlan.push({ config: c, ticket: t.id, k, base: true })

phase('Trials')
const rows = await inBatches(basePlan.map((p) => () => runTrial(p)))
log(`Trials: ${rows.filter((r) => r.status === 'completed').length} completed of ${rows.length} planned`)

// ---------- Scan (code only, no agent) ----------
const FORBIDDEN = [
  /\bspe\/(evals|predictions|plans)\b/,
  /answers\.json/,
  /grade\.py/,
  /judge\.md/,
  /\br\d{2}(-draft)?\.yaml\b/,
  /\bgit\s+(log|show|diff|grep|blame)\b/,
]
const SUSPECT = [/\b(grep|rg|ag)\b[^|]*\s-[a-zA-Z]*[rR]/, /\bfind\s+\.(\s|$)/, /\bls\s+-[a-zA-Z]*R/, /(^|[\s'"\/])spe(\/|\s|$)/]

function scan(list) {
  for (const r of list) {
    if (r.status !== 'completed') continue
    const touched = [...(r.out.files_read ?? []), ...(r.out.commands_run ?? [])]
    const hit = touched.find((s) => FORBIDDEN.some((re) => re.test(s)))
    if (hit) {
      r.status = 'voided_peek'
      r.void_reason = hit.slice(0, 200)
      continue
    }
    if (r.out.ticket_id !== r.ticket) {
      r.status = 'voided_mismatch'
      r.void_reason = `returned ticket_id ${r.out.ticket_id}`
      continue
    }
    r.suspect = touched.filter((s) => SUSPECT.some((re) => re.test(s)))
  }
  const voided = list.filter((r) => r.status.startsWith('voided'))
  if (voided.length) log(`Scan voided ${voided.length} trials: ${voided.map((r) => r.label).join(', ')}`)
}

phase('Scan')
scan(rows)

// ---------- Grade (code check through grade.py) ----------
function gradePrompt(file, input) {
  return [
    'You run a code grader. You do not grade anything yourself.',
    `1. Write this JSON array to ${file} exactly as given. Create the folder if it is missing.`,
    JSON.stringify(input),
    `2. Run: python3 ${PATHS.grader} --answers ${PATHS.answers} --input ${file} --json`,
    '3. Return the exit code. For every key in the grader output, return key, category_ok, and priority_ok exactly as the grader printed them.',
    'Do not change, add, or drop any key. If the command fails, return the exit code and an empty results list.',
  ].join('\n')
}

async function gradeAll(list, tag, phaseName) {
  const todo = list.filter((r) => r.status === 'completed' && !r.graded)
  const thunks = chunk(todo, GRADE_BATCH).map((b, i) => async () => {
    const what = `r${RR}-grade-${tag}-${i + 1}`
    if (!reserve('grade', what, { fromHeld: true })) {
      b.forEach((r) => (r.grade_error = 'skipped_budget'))
      return
    }
    const input = b.map((r) => ({
      key: r.label,
      ticket_id: r.ticket,
      label: { category: r.out.label.category, priority: r.out.label.priority },
    }))
    try {
      const g = await agent(gradePrompt(`${PATHS.runDir}/grade-input-${tag}-${i + 1}.json`, input), {
        label: what,
        phase: phaseName,
        schema: GRADE_SCHEMA,
        model: MODEL.grade,
      })
      const byKey = new Map(g.results.map((x) => [x.key, x]))
      if (g.exit_code !== 0 || byKey.size !== b.length) {
        log(`GRADER PROBLEM in ${what}: exit ${g.exit_code}, ${byKey.size} keys for ${b.length} trials`)
        b.forEach((r) => (r.grade_error = `exit ${g.exit_code}, key count ${byKey.size}/${b.length}`))
        return
      }
      for (const r of b) {
        const x = byKey.get(r.label)
        if (!x) {
          r.grade_error = 'missing key'
          continue
        }
        r.graded = true
        r.category_ok = x.category_ok
        r.priority_ok = x.priority_ok
        r.label_ok = x.category_ok && x.priority_ok
      }
    } catch (e) {
      b.forEach((r) => (r.grade_error = errText(e)))
    }
  })
  await inBatches(thunks, 5)
}

phase('Grade')
await gradeAll(rows, 'base', 'Grade')
const gradeErrors = rows.filter((r) => r.grade_error && r.grade_error !== 'skipped_budget')
if (gradeErrors.length > 0.2 * rows.filter((r) => r.status === 'completed').length) {
  return halt('the grader failed on more than 20% of completed trials, so it is treated as broken', {
    grade_errors: gradeErrors.map((r) => ({ label: r.label, error: r.grade_error })),
  })
}

// ---------- Top-up ----------
function cellTable(list) {
  const m = {}
  for (const r of list) {
    const key = `${r.config}:${r.ticket}`
    m[key] ??= { config: r.config, ticket: r.ticket, n: 0, pass: 0, n_base: 0, pass_base: 0 }
    if (!r.graded) continue
    m[key].n++
    if (r.label_ok) m[key].pass++
    if (r.base) {
      m[key].n_base++
      if (r.label_ok) m[key].pass_base++
    }
  }
  return m
}

phase('Top-up')
if (DRY) {
  log('Dry run: top-up is skipped.')
} else {
  const split = Object.values(cellTable(rows)).filter((c) => c.n > 0 && c.pass > 0 && c.pass < c.n)
  const topPlan = []
  for (let j = 1; j <= TOPUP_PER_CELL; j++)
    for (const c of split) if (topPlan.length < TOPUP_MAX) topPlan.push({ config: c.config, ticket: c.ticket, k: TRIALS + j, base: false })
  log(`Top-up: ${split.length} split cells, ${topPlan.length} extra trials (at most ${TOPUP_PER_CELL} per cell and ${TOPUP_MAX} in total)`)
  const extra = await inBatches(topPlan.map((p) => () => runTrial(p)))
  scan(extra)
  await gradeAll(extra, 'topup', 'Top-up')
  rows.push(...extra)
}

// ---------- Judge (tone only, blind to config) ----------
phase('Judge')
log('The judge is Opus, the same model family as the trials. No judge from another family is available, so they may share blind spots.')
const rand = rng(A.seed ?? 7919)
const judgeItems = shuffle(rows.filter((r) => r.status === 'completed'), rand).map((r, i) => ({
  r,
  id: `item-${String(i + 1).padStart(4, '0')}`,
}))
const judgeThunks = chunk(judgeItems, JUDGE_BATCH).map((b, i) => async () => {
  const what = `r${RR}-judge-${i + 1}`
  if (!reserve('judge', what, { fromHeld: true })) return
  const items = b.map(({ r, id }) => ({
    id,
    ticket_subject: ticketById[r.ticket].subject,
    ticket_body: ticketById[r.ticket].body,
    reply: r.out.reply,
  }))
  try {
    const j = await agent(
      [
        `You grade the tone of customer replies. Read the rubric at ${PATHS.judge} and apply it exactly.`,
        'Do not read any other file under spe/. You do not know which configuration wrote each reply. Do not guess.',
        'Judge tone only. Do not judge whether the category or priority is right.',
        "For each item, return id, tone_pass using the rubric's pass line, tone_score from 1 to 5, and a one-sentence reason that quotes the reply.",
        'Items:',
        JSON.stringify(items),
      ].join('\n'),
      { label: what, phase: 'Judge', schema: JUDGE_SCHEMA, model: MODEL.judge },
    )
    const byId = new Map(j.scores.map((s) => [s.id, s]))
    for (const { r, id } of b) {
      const s = byId.get(id)
      if (!s) {
        r.judge_error = 'missing id'
        continue
      }
      r.tone_pass = s.tone_pass
      r.tone_score = s.tone_score
      r.tone_reason = s.reason
    }
  } catch (e) {
    b.forEach(({ r }) => (r.judge_error = errText(e)))
  }
})
await inBatches(judgeThunks, 5)

// ---------- Metrics ----------
function summarize(list) {
  const done = list.filter((r) => r.status === 'completed')
  const graded = done.filter((r) => r.graded)
  const judged = done.filter((r) => r.tone_pass !== undefined)
  const calls = done.reduce((s, r) => s + r.out.tool_calls, 0)
  const errs = done.reduce((s, r) => s + r.out.tool_errors, 0)
  return {
    planned: list.length,
    completed: done.length,
    skipped_budget: list.filter((r) => r.status === 'skipped_budget').length,
    harness_errors: list.filter((r) => r.status === 'harness_error').length,
    voided: list.filter((r) => r.status.startsWith('voided')).length,
    suspect: done.filter((r) => r.suspect?.length).length,
    n_graded: graded.length,
    label_accuracy: rate(graded.filter((r) => r.label_ok).length, graded.length),
    category_accuracy: rate(graded.filter((r) => r.category_ok).length, graded.length),
    priority_accuracy: rate(graded.filter((r) => r.priority_ok).length, graded.length),
    n_judged: judged.length,
    tone_pass_rate: rate(judged.filter((r) => r.tone_pass).length, judged.length),
    tone_mean_score: mean(judged.map((r) => r.tone_score)),
    runtime_ms_mean: mean(done.map((r) => r.runtime_ms)),
    tool_calls_mean: mean(done.map((r) => r.out.tool_calls)),
